import type {ListKind} from './capture';
// Alkuperäiset listapohjat (Tuntilista Ajuri.xlsx ja Pamark ajolista.xlsx) upotettuina. O103-viite korjattu I100:ksi.
const base64:Record<ListKind,string>={hours:"",pamark:""};
export function bundledTemplateBytes(kind:ListKind):Uint8Array{const raw=atob(base64[kind]);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes;}
